CREATE TABLE "users" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "username" TEXT NOT NULL UNIQUE, "full_name" TEXT NOT NULL, "password_hash" TEXT NOT NULL, "role" TEXT NOT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "last_login_at" INTEGER NULL, "uuid" TEXT NULL);
CREATE TABLE "categories" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE, "uuid" TEXT NULL);
CREATE TABLE "units" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE, "uuid" TEXT NULL);
CREATE TABLE "products" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "code" TEXT NOT NULL UNIQUE, "barcode" TEXT NULL UNIQUE, "name" TEXT NOT NULL, "category_id" INTEGER NULL REFERENCES categories (id), "unit_id" INTEGER NULL REFERENCES units (id), "purchase_price" INTEGER NOT NULL DEFAULT 0, "selling_price" INTEGER NOT NULL DEFAULT 0, "stock" REAL NOT NULL DEFAULT 0.0, "min_stock" REAL NOT NULL DEFAULT 0.0, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "uuid" TEXT NULL);
CREATE TABLE "sales" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "invoice_no" TEXT NOT NULL UNIQUE, "sale_date" INTEGER NOT NULL, "user_id" INTEGER NOT NULL REFERENCES users (id), "item_count" INTEGER NOT NULL, "subtotal" INTEGER NOT NULL, "discount_percent" REAL NULL, "discount" INTEGER NOT NULL DEFAULT 0, "total" INTEGER NOT NULL, "paid" INTEGER NOT NULL, "change_amount" INTEGER NOT NULL, "payment_method" TEXT NOT NULL DEFAULT 'tunai', "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "voucher_id" INTEGER NULL REFERENCES vouchers (id), "voucher_code" TEXT NULL, "payment_method_id" INTEGER NULL REFERENCES payment_methods (id), "payment_ref" TEXT NULL, "terminal_code" TEXT NULL, "uuid" TEXT NULL);
CREATE TABLE "sale_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "sale_id" INTEGER NOT NULL REFERENCES sales (id) ON DELETE CASCADE, "product_id" INTEGER NOT NULL REFERENCES products (id), "product_code" TEXT NOT NULL, "product_name" TEXT NOT NULL, "unit_name" TEXT NULL, "qty" REAL NOT NULL, "price" INTEGER NOT NULL, "discount_percent" REAL NOT NULL DEFAULT 0.0, "purchase_price" INTEGER NOT NULL, "subtotal" INTEGER NOT NULL, "uuid" TEXT NULL);
CREATE TABLE "stock_movements" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "product_id" INTEGER NOT NULL REFERENCES products (id), "type" TEXT NOT NULL, "qty_change" REAL NOT NULL, "ref_id" INTEGER NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "uuid" TEXT NULL);
CREATE INDEX idx_products_name ON products (name);
CREATE INDEX idx_sales_date ON sales (sale_date);
CREATE TABLE "vouchers" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "code" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL DEFAULT '', "type" TEXT NOT NULL, "value" REAL NOT NULL, "max_discount" INTEGER NULL, "min_purchase" INTEGER NOT NULL DEFAULT 0, "start_date" INTEGER NULL, "end_date" INTEGER NULL, "quota" INTEGER NULL, "used_count" INTEGER NOT NULL DEFAULT 0, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "uuid" TEXT NULL);
CREATE TABLE "payment_methods" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE, "kind" TEXT NOT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "uuid" TEXT NULL);
CREATE TABLE "settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "sync_outbox" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "entity" TEXT NOT NULL, "entity_uuid" TEXT NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "attempts" INTEGER NOT NULL DEFAULT 0, "last_attempt_at" INTEGER NULL, "last_error" TEXT NULL, "sent_at" INTEGER NULL);
CREATE INDEX idx_sync_outbox_pending ON sync_outbox (sent_at, id);
CREATE UNIQUE INDEX idx_users_uuid ON users (uuid);
CREATE UNIQUE INDEX idx_categories_uuid ON categories (uuid);
CREATE UNIQUE INDEX idx_units_uuid ON units (uuid);
CREATE UNIQUE INDEX idx_products_uuid ON products (uuid);
CREATE UNIQUE INDEX idx_vouchers_uuid ON vouchers (uuid);
CREATE UNIQUE INDEX idx_payment_methods_uuid ON payment_methods (uuid);
CREATE UNIQUE INDEX idx_sales_uuid ON sales (uuid);
CREATE UNIQUE INDEX idx_sale_items_uuid ON sale_items (uuid);
CREATE UNIQUE INDEX idx_stock_movements_uuid ON stock_movements (uuid);
